import{_ as s,H as i,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"11 | 实现：基于HBase的手机云服务数据存储设计","description":"","frontmatter":{},"headers":[{"level":2,"title":"单元化与数据备份","slug":"单元化与数据备份","link":"#单元化与数据备份","children":[{"level":3,"title":"数据是否会循环复制？","slug":"数据是否会循环复制","link":"#数据是否会循环复制","children":[]},{"level":3,"title":"数据顺序能否保证？","slug":"数据顺序能否保证","link":"#数据顺序能否保证","children":[]}]},{"level":2,"title":"表与行键的设计","slug":"表与行键的设计","link":"#表与行键的设计","children":[{"level":3,"title":"表字段与存储优化","slug":"表字段与存储优化","link":"#表字段与存储优化","children":[]},{"level":3,"title":"行键设计","slug":"行键设计","link":"#行键设计","children":[]}]},{"level":2,"title":"迁移保障","slug":"迁移保障","link":"#迁移保障","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"分布式数据库从入门到实战/11｜实现：基于HBase的手机云服务数据存储设计.md","filePath":"分布式数据库从入门到实战/11｜实现：基于HBase的手机云服务数据存储设计.md","lastUpdated":1795541719000}'),t={name:"分布式数据库从入门到实战/11｜实现：基于HBase的手机云服务数据存储设计.md"};function l(n,a,h,r,k,o){return i(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="_11-实现-基于hbase的手机云服务数据存储设计" tabindex="-1">11 | 实现：基于HBase的手机云服务数据存储设计 <a class="header-anchor" href="#_11-实现-基于hbase的手机云服务数据存储设计" aria-label="Permalink to &quot;11 | 实现：基于HBase的手机云服务数据存储设计&quot;">​</a></h1><p>你好，我是彭旭。</p><p>前面几节课，我们探讨了 HBase 实现分区弹性伸缩，优化实时随机存取性能，以及实现高可用的方法。HBase 的这些特性解决了手机云服务系统的运维需求、成本需求和高性能需求。为云服务采用 HBase 作为新的存储方案提供了理论上的支撑。</p><p>这节课我们再来看看，如果采用 HBase 作为新的存储引擎，系统架构设计是怎样的，过程中又可能遇到什么问题。</p><p>这节课会复习到前面讲解过的如何基于业务场景设计 HBase 行键，如何优化列限定符来减少存储空间。同时，我也会讲一个新的知识点，HBase 如何实现跨集群数据的实时复制，完成单元化、集群数据汇总分析。</p><h2 id="单元化与数据备份" tabindex="-1">单元化与数据备份 <a class="header-anchor" href="#单元化与数据备份" aria-label="Permalink to &quot;单元化与数据备份&quot;">​</a></h2><p>你应该还记得我们讲云服务需求的时候有提到，多机房的目标本来是单元化，也就是每个机房能够独立提供服务，具备数据的完整性。但是因为 MySQL 使用 SSD 存储，导致了巨大的成本压力，最后每个机房只存储了一部分的数据，所有机房加起来才是一份完整的数据。这样其实没有做到真正的单元化，而且数据也没有多机房的容灾。</p><p>其实使用 HBase 作为新的存储引擎后，这几个问题很容易就解决了。</p><p>首先，HBase 可以使用机械硬盘存储，使用编码与压缩，也能较大地压缩数据存储空间。这样整体的存储硬件成本至少能够减少 50%。</p><p>其次，HBase 提供了多种数据备份容灾的方式。比如使用 replication 可以在集群之间实时复制数据，可以使用快照、导入导出对集群数据做定期冷备容灾等。这样就实现了多机房多副本数据备份与容灾。</p><p>所以我们在每个机房都搭建了一个 HBase 集群，然后使用 replication 来在这些集群之间实时复制数据。这样每个机房都有一份完整的数据，真正做到了单元化。</p><p>换了存储引擎后，系统架构就像下面这张图 一样了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%93%E4%BB%8E%E5%85%A5%E9%97%A8%E5%88%B0%E5%AE%9E%E6%88%98/images/11/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%95%B0%E6%8D%AE%E5%BA%93%E4%BB%8E%E5%85%A5%E9%97%A8%E5%88%B0%E5%AE%9E%E6%88%98/images/11/1.png" alt=""></a></p><p>你可以看到整个系统的业务逻辑层基本没有变化，只是换了一个存储层。然后在存储层的不同机房集群之间配置了实时复制。注意，配置复制的时候，并不需要整个集群一起复制，你可以灵活地配置到表的列族级别复制。</p><h3 id="数据是否会循环复制" tabindex="-1">数据是否会循环复制？ <a class="header-anchor" href="#数据是否会循环复制" aria-label="Permalink to &quot;数据是否会循环复制？&quot;">​</a></h3><p>但是集群之间数据实时复制，又会遇到一些新的问题。</p><p>比如数据 A 写入 NS 集群后，发现有一个到 WX 集群的复制链接，那么 A 就会被复制到 WX集群。当 A 写入到 WX 集群后，发现 WX 集群又有一个到 NS 集群的复制链接，结果 A 又被复制到了 NS 集群。</p><p>那么 HBase 如何解决这种循环复制的问题呢？</p><p>其实，集群间 replication 是采用数据源推的方式，如果某个表的列族配置了复制，当这个列族下分区的 WAL（Write-Ahead-Log）有更新时，RegionServer 会将这个 WAL 推送到配置了复制链接的目标集群。是不是跟关系型数据库的 binlog 同步很像？</p><p>当数据从源集群复制到目标集群的时候，WAL 里面的数据会记录下源集群的唯一标识符clusterID，HBase 会将所有已经消费过数据的集群 clusterID 记录下来，防止数据的循环复制（如 A→B→C→A）。</p><p>这里提一下，数据复制的单元是 WALEntry，由 WALEdit 和 WALKey 组成，WALEdit 是变更的数据，WALKey 用来记录已经复制过的集群标识符。</p><h3 id="数据顺序能否保证" tabindex="-1">数据顺序能否保证？ <a class="header-anchor" href="#数据顺序能否保证" aria-label="Permalink to &quot;数据顺序能否保证？&quot;">​</a></h3><p>跟消息中间件消息投递的可靠性保障一样，HBase 为复制提供了至少投递一次的语义。这样可以保证所有的目标集群都能收到需要复制的数据。</p><p>这样又带来了一个新的问题，数据的有序性就可能无法保证了。</p><p>比如分区 X 原来由 RegionServer A 负责，在 RegionServer A 异常下线之后，分区 X 转移到RegionServer B，如果 RegionServer A 上数据 M 未复制完成，保存在一个数据队列，这个数据队列，也正好转移到 RegionServer B 负责复制。那这个时候，分区 X 上新增的数据 N 可能已经通过 RegionServer B 复制完成，但是比 N 更旧的数据 M 还没复制好。</p><p>也就是说，当目标集群的某个 RegionServer 异常后，因为复制过程是异步的，新复制的数据可能会与尚未复制的数据发生顺序上的交错，导致数据更新的顺序无法保证，因此复制的时候无法保证数据更新的顺序不变。</p><p>所以，某些非幂等（f(x) = x）的操作（如 Increments）复制到从集群后，目标集群数据可能与源集群不一致，设计应用程序的时候需要特别注意这个特性。</p><p>不过 HBase2.1 以后，HBase 提供了一个串行化复制的能力，串行化复制能够将日志按照到达源集群的顺序推送到目标集群，从而保障数据的有序性。</p><p>好，单元化部署、高可用与数据的备份问题解决了，对存储层来说，剩下的就是数据模型怎么设计的问题了。</p><h2 id="表与行键的设计" tabindex="-1">表与行键的设计 <a class="header-anchor" href="#表与行键的设计" aria-label="Permalink to &quot;表与行键的设计&quot;">​</a></h2><p>其实云服务涉及的一些业务，像通话记录、联系人、短信等业务上不会相互关联，数据模型扁平化，所以基本都可以用一张宽表存储。实际上在 MySQL 中就是这样，到了 HBase 中，有什么变化呢？</p><h3 id="表字段与存储优化" tabindex="-1">表字段与存储优化 <a class="header-anchor" href="#表字段与存储优化" aria-label="Permalink to &quot;表字段与存储优化&quot;">​</a></h3><p>首先，HBase 是动态 schema，表的字段可以根据行的需求动态添加，所以建表时只需要声明表名字，以及配置一些优化表存储的属性，如使用压缩、预先分区等。像下面这个联系人表s_contact，启用了布隆过滤器，使用 Snappy 压缩，开启复制，又将表分成了 10 个分区。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>create &#39;s_contact&#39;, {NAME=&gt;&#39;cf&#39;,BLOOMFILTER=&gt;&#39;ROW&#39;,</span></span>
<span class="line"><span>REPLICATION_SCOPE=&gt;&#39;1&#39;,COMPRESSION=&gt;&#39;SNAPPY&#39;},</span></span>
<span class="line"><span>{SPLITS=&gt;[&#39;1&#39;,&#39;2&#39;,&#39;3&#39;,&#39;4&#39;,&#39;5&#39;,&#39;6&#39;,&#39;7&#39;,&#39;8&#39;,&#39;9&#39;]}</span></span></code></pre></div><p>不过最终实际线上环境中，表的分区远远不止 10 个，在一个几十个节点的集群中，最终像短信、</p><p>通话记录这些表，分区数都在一百以上。而且在系统运行过程中，我们一直在根据分区的数据量大小进行手动拆表。</p><p>其次，由于每行数据的列都可以不同，而 HBase 又使用了一个 KeyValue 的键值对存储列与值，所以，每行数据都会把列限定符（也就是列名）存储一次。如果列限定符较长，占用空间就大。因此，我们也做了一个列限定符的精简映射。比如通话记录表，将电话号码、通话时长等字段，全部用最少得字符来表示。这样就可以尽可能的节省存储空间。</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CallD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> long</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> u;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//userId</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> private</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> String p </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//电话号码 number</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> long</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> d;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//日期 date</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//通话时长 duration</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> t;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//通话类型（来电：1;去电：2;Missed:3;voiceMail:4;录音:5;录音失败：6）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   ....</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>最后再来看看表的行键如何设计。</p><h3 id="行键设计" tabindex="-1">行键设计 <a class="header-anchor" href="#行键设计" aria-label="Permalink to &quot;行键设计&quot;">​</a></h3><p>你应该已经知道了，从技术上讲，表分区与行键的设计需要做到让数据均衡分布，同时将查询条件尽可能融到行键里面，提升数据读取效率。而从业务场景上，需要支持云服务数据的全量同步与增量同步。</p><p>我们云服务的数据都是用户隔离的，每个用户肯定只能看到自己的数据。所以，为了避免信息泄露或者越权访问，甚至连客户端也做了用户数据的对比。假设同步请求访问到了不该访问的数据，最终也会被客户端过滤掉。当然这个只是最后一层安全保障，实际上并不会发生。</p><p>具体来说，业务上每个同步请求，用户 ID 都是一个必填项，所以行键开头就使用用户 ID。同时，为了避免热点区间，还要对用户 ID 做反转补齐。</p><p>行键的第二个组成部分有两个选项，第一个是选用数据的更新时间，第二个是选用数据的唯一标识 UUID。</p><p>到底如何组合呢？从业务场景出发来分析一下。</p><p>全量同步的时候，需要拉取用户所有的数据，这里会以用户 ID 作为前缀，区间扫描，所以使用两个方案都没影响。</p><p>至于增量同步，需要从两个维度来看。</p><ol><li>从服务端拉取某个时间点后更新的数据到客户端。</li></ol><p>这时候，如果行键是用户 ID+ 数据更新时间，就可以更进一步缩小需要扫描数据的范围。如果行键是用户 ID+UUID，则需要扫描用户所有数据，然后在 Scan 中增加时间作为过滤条件。</p><ol start="2"><li>从客户端更新一行或者多行数据到服务端。</li></ol><p>这个时候就需要根据更新数据的 UUID，从服务端找到对应的数据进行更新。</p><p>这种情况如果行键是用户 ID+UUID，那是不是直接做一个数据写入就行了？也不需要去查询数据是否存在。如果行键是用户 ID+ 数据更新时间，那么就需要从用户所有数据中，找到更新的这条记录，然后用找到记录的行键删除旧数据，再构造新行键写入新数据。</p><p>最后综合来看，行键选用用户 ID+UUID 读写成本会更低，而且排查问题的时候，更容易找到数据。所以我们最后选择了用户 ID+ 数据 UUID 作为行键的方案。</p><p>确定了系统架构、表设计与行键设计，就可以开始数据迁移了。</p><h2 id="迁移保障" tabindex="-1">迁移保障 <a class="header-anchor" href="#迁移保障" aria-label="Permalink to &quot;迁移保障&quot;">​</a></h2><p>虽然有一些数据迁移工具，如 Sqoop，可以将 MySQL 数据迁移到 HBase，但是为了能够实时保证数据的一致，同时也方便两边数据的实时对比，所以最后我们还是自己写了程序来做数据的迁移。同时也通过程序对比两边的数据数量与抽样校验。</p><p>业务请求上我们也是按业务类型（比如通话记录与联系人）、按流量比例分批迁移。通过制定一系列的迁移策略，以配置开关来实时调整，切换哪个业务、多少百分比用户流量到 HBase集群读写。这样来最终保障系统的稳定。</p><p>在读写策略上，整个迁移过程分为了 3 个阶段，保证出问题了能够随时回滚。</p><p>第 1 阶段：双写 MySQL 与 HBase，读 MySQL。</p><p>第 2 阶段：双写 MySQL 与 HBase，读 HBase。</p><p>第 3 阶段：等到验证服务与数据都没问题后，改成单读写 HBase。</p><p>通过将数据、流量分批逐步迁移到 HBase，这个过程也是对 HBase 一个调优与压力测试的过程。最终准确地评估出 HBase 集群的节点与存储规模。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>好了，我们总结一下。HBase 的复制能力真正实现了多机房的单元化，而且每个机房都存储了一份完整的数据，可以用来做灾备。当然 MySQL 也可以做跨机房的主主复制，但是成本上相对更高。</p><p>由于 HBase 不支持 Join，所以对于需要星型或者雪花型数据模型架构的场景支持不好，建议就是一个业务场景能用一张或者少数张的表搞定。</p><p>基于 HBase 存储的模型设计主要是在表如何分区、行键如何设计上。在避免热点区间的同时，将查询条件尽可能的融到行键上。</p><p>你应该还记得前面提到 HBase 只支持单行事务，所以从 MySQL 迁移到 HBase 的时候，也要注意到程序中用到的事务。要么将关联数据一行写入，要么用程序来实现最终一致性的保障。</p><p>虽然一切看起来都设计妥当了，逻辑也比较简单。但是实际上迁移过程中还是出现了很多问题。</p><p>比如 HBase 集群的自动 Split 与 Compact 导致系统响应慢。比如因为数据写多读少，磁盘出现瓶颈，磁盘 IO 使用率过高等。</p><p>下一节课，我们就来看看如何针对这些问题进行调优。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>行键设计的时候最终选用了用户 ID+UUID 的方案，你觉得能否使用三个字段组合的方式？或者你还有没有其他优化的方案?</p><p>欢迎你在留言区和我交流。如果觉得有所收获，也可以把课程分享给更多的朋友一起学习。欢迎你加入我们的读者交流群，我们下节课见！</p>`,73)])])}const g=s(t,[["render",l]]);export{c as __pageData,g as default};
